import * as THREE from "three";
import type { Look } from "@/lib/story/looks";

export type FaceMaterial = { material: THREE.MeshStandardMaterial; set: (from: THREE.Texture, to: THREE.Texture, amount: number) => void };
export function faceMaterial(look: Look, blank: THREE.Texture): FaceMaterial {
  const first = { value: blank };
  const second = { value: blank };
  const amount = { value: 0 };
  const material = new THREE.MeshStandardMaterial({
    color: look.surface.glows ? look.surface.color : "#ffffff",
    roughness: look.surface.roughness,
    metalness: 0,
    side: THREE.DoubleSide,
    map: blank,
    emissive: look.surface.glows ? "#ffffff" : "#000000",
    emissiveIntensity: look.surface.glows ? 1 : 0,
    emissiveMap: look.surface.glows ? blank : null,
    toneMapped: look.surface.glows,
  });
  material.onBeforeCompile = shader => {
    shader.uniforms.storyFrom = first;
    shader.uniforms.storyTo = second;
    shader.uniforms.storyAmount = amount;
    shader.fragmentShader = `uniform sampler2D storyFrom;\nuniform sampler2D storyTo;\nuniform float storyAmount;\n${shader.fragmentShader}`;
    const sample = "mix(texture2D(storyFrom, vMapUv), texture2D(storyTo, vMapUv), storyAmount)";
    shader.fragmentShader = shader.fragmentShader.replace("#include <map_fragment>", look.surface.glows ? "" : `diffuseColor *= ${sample};`);
    if (look.surface.glows) shader.fragmentShader = shader.fragmentShader.replace("#include <emissivemap_fragment>", `totalEmissiveRadiance *= ${sample}.rgb;`);
  };
  material.customProgramCacheKey = () => `story-face-v1-${look.surface.glows}`;
  return { material, set(from, to, mix) { first.value = from; second.value = to; amount.value = mix; } };
}
import * as THREE from "three";
import type { Look } from "@/lib/story/looks";
import type { FaceDef } from "./types";

/** Drawing is queued; at most two faces are painted by one animation frame. */
export function createFaces(faces: readonly FaceDef[], look: Look, coarse: boolean) {
  let disposed = false;
  const value = look.surface.glows ? 0 : 255;
  const blank = new THREE.DataTexture(new Uint8Array([value, value, value, 255]), 1, 1);
  blank.colorSpace = THREE.SRGBColorSpace;
  blank.needsUpdate = true;
  const made = new Map<string, { canvas: HTMLCanvasElement; texture: THREE.CanvasTexture }>();
  const images = new Map<string, HTMLImageElement>();
  const loading: HTMLImageElement[] = [];
  const waiting = [...faces];
  const queued = new Set(faces.map(face => face.id));
  const queue = (face: FaceDef) => { if (!disposed && !queued.has(face.id)) { waiting.push(face); queued.add(face.id); } };
  for (const face of faces) if (face.src) {
    const picture = new Image();
    loading.push(picture);
    picture.crossOrigin = "anonymous";
    picture.onload = () => { if (!disposed) { images.set(face.id, picture); queue(face); } };
    picture.onerror = () => { /* The background and any canvas drawing remain readable. */ };
    picture.src = face.src;
  }
  void document.fonts.ready.then(() => { if (!disposed) faces.forEach(queue); });
  return {
    blank,
    get(beat: string, piece: number) {
      const face = faces.find(item => item.beat === beat && item.piece === piece);
      return face ? made.get(face.id)?.texture ?? blank : blank;
    },
    draw() {
      for (let n = 0; n < 2 && waiting.length && !disposed; n++) {
        const face = waiting.shift()!;
        queued.delete(face.id);
        let record = made.get(face.id);
        if (!record) {
          const canvas = document.createElement("canvas");
          canvas.width = coarse ? 384 : 768; canvas.height = coarse ? 512 : 1024;
          const texture = new THREE.CanvasTexture(canvas);
          texture.colorSpace = THREE.SRGBColorSpace;
          record = { canvas, texture }; made.set(face.id, record);
        }
        const { canvas, texture } = record;
        const context = canvas.getContext("2d");
        if (!context) continue;
        context.clearRect(0, 0, canvas.width, canvas.height);
        context.fillStyle = look.surface.glows ? "#000000" : look.surface.color;
        context.fillRect(0, 0, canvas.width, canvas.height);
        const picture = images.get(face.id);
        if (picture) context.drawImage(picture, 0, 0, canvas.width, canvas.height);
        context.save();
        face.draw?.(context, canvas.width, canvas.height, look);
        context.restore();
        texture.needsUpdate = true;
      }
    },
    dispose() {
      disposed = true;
      for (const image of loading) { image.onload = null; image.onerror = null; }
      images.clear();
      for (const { texture } of made.values()) texture.dispose();
      made.clear(); waiting.length = 0; blank.dispose();
    },
  };
}
"use client";
import { useSyncExternalStore } from "react";
import { lookFromSearch, searchWithLook, type Look } from "@/lib/story/looks";
const event = "story-look";
function subscribe(notify: () => void) {
  window.addEventListener("popstate", notify);
  window.addEventListener(event, notify);
  return () => { window.removeEventListener("popstate", notify); window.removeEventListener(event, notify); };
}
export function useLook(looks: readonly Look[], defaultLook = looks[0].id) {
  return useSyncExternalStore(subscribe, () => lookFromSearch(window.location.search, looks, defaultLook), () => defaultLook);
}
export function chooseLook(id: string, defaultLook: string) {
  const { pathname, search, hash } = window.location;
  window.history.replaceState(window.history.state, "", `${pathname}${searchWithLook(search, id, defaultLook)}${hash}`);
  window.dispatchEvent(new Event(event));
}
"use client";
import { useCallback, useEffect, useMemo, useRef, useState, type CSSProperties, type ReactNode } from "react";
import dynamic from "next/dynamic";
import type { Stage } from "@/lib/story/camera";
import { createControls } from "@/lib/story/controls";
import { playhead, type BeatBox, type Playhead } from "@/lib/story/timeline";
import { useReducedMotion } from "./use-reduced-motion";
import { useWebGLSupported } from "./use-webgl-supported";
import { useLook } from "./use-look";
import { WebGLBoundary } from "./webgl-boundary";
import { LookSwitch } from "./look-switch";
import { ChapterRail } from "./rail";
import { Overlay } from "./overlay";
import { Meter } from "./meter";
import { ControlsProvider } from "./controls";
import { checkBundle } from "./validate";
import type { StoryBundle } from "./types";
const Scene = dynamic(() => import("./scene"), { ssr: false });

export function Story({ bundle, children }: { bundle: StoryBundle; children: ReactNode }) {
  const issues = useMemo(() => checkBundle(bundle), [bundle]);
  if (issues.length) throw new Error(`Invalid story: ${issues.join("; ")}`);
  const rootRef = useRef<HTMLDivElement>(null);
  const headRef = useRef<Playhead>({ beat: 0, dwell: 0 });
  const stageRef = useRef<Stage>({ viewport: 0, header: 0, captions: [] });
  const pointerRef = useRef({ x: 0, y: 0 });
  const fpsRef = useRef(0);
  const [controls] = useState(createControls);
  const webgl = useWebGLSupported();
  const still = useReducedMotion();
  const [failed, setFailed] = useState(false);
  const [running, setRunning] = useState(true);
  const [activeChapter, setActiveChapter] = useState<string | undefined>(bundle.story.chapters[0]?.id);
  const onError = useCallback(() => setFailed(true), []);
  const id = useLook(bundle.looks, bundle.defaultLook);
  const look = bundle.looks.find(look => look.id === id) ?? bundle.looks[0];
  const on = webgl === true && !failed;
  const items = useMemo(() => bundle.story.chapters.map(chapter => ({ id: chapter.id, number: chapter.number, label: chapter.name })), [bundle.story]);
  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    let boxes: BeatBox[] = [];
    const update = () => { headRef.current = playhead(-root.getBoundingClientRect().top, window.innerHeight, boxes); };
    const measure = () => {
      const origin = root.getBoundingClientRect().top;
      const beats = Array.from(root.querySelectorAll<HTMLElement>("[data-beat]"));
      boxes = beats.map(beat => { const box = beat.getBoundingClientRect(); return { top: box.top - origin, height: box.height }; });
      const top = root.querySelector<HTMLElement>("[data-story-top]");
      stageRef.current = { viewport: window.innerHeight, header: top ? top.offsetTop + top.offsetHeight : 0, captions: beats.map(beat => {
        const caption = beat.querySelector<HTMLElement>(".story-caption");
        const text = beat.querySelector<HTMLElement>(".story-caption-text");
        return caption && text ? text.getBoundingClientRect().height + parseFloat(getComputedStyle(caption).paddingBottom) : 0;
      }) };
      update();
    };
    measure();
    const resize = new ResizeObserver(measure);
    resize.observe(root);
    root.querySelectorAll(".story-caption-text").forEach(node => resize.observe(node));
    let visible = true;
    const visibility = () => setRunning(visible && !document.hidden);
    const seen = new IntersectionObserver(([entry]) => { visible = entry.isIntersecting; visibility(); });
    seen.observe(root);
    document.addEventListener("visibilitychange", visibility);
    window.addEventListener("scroll", update, { passive: true });
    window.addEventListener("resize", measure);
    return () => { resize.disconnect(); seen.disconnect(); window.removeEventListener("scroll", update); window.removeEventListener("resize", measure); document.removeEventListener("visibilitychange", visibility); };
  }, [bundle.story, on]);
  useEffect(() => {
    if (still) { pointerRef.current = { x: 0, y: 0 }; return; }
    const move = (event: PointerEvent) => { if (event.pointerType === "mouse") pointerRef.current = { x: event.clientX / window.innerWidth * 2 - 1, y: 1 - event.clientY / window.innerHeight * 2 }; };
    window.addEventListener("pointermove", move, { passive: true });
    return () => window.removeEventListener("pointermove", move);
  }, [still]);
  const style = { "--story-ground": look.ground, "--story-ink": look.ink, "--story-faint": look.faint, "--story-accent": look.accent } as CSSProperties;
  return <ControlsProvider controls={controls} sceneOff={!on}><div ref={rootRef} className="story" data-scene={on ? "on" : "off"} data-look={look.id} style={style}>
    <noscript><style>{".story-look-switch, .story-control { display: none !important; }"}</style></noscript>
